for (let item of $input.all()) {
  let text = item.json.message?.content || item.json.content || item.json.text || "";
  if (typeof text !== 'string') text = JSON.stringify(text);
  text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

  let inString = false;
  let escaped = false;
  let result = '';
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char === '"' && !escaped) {
      inString = !inString;
      result += char;
    } else if (char === '\\' && !escaped) {
      escaped = true;
      result += char;
    } else {
      escaped = false;
      if (inString) {
        if (char === '\n') result += '\\n';
        else if (char === '\r') result += '\\r';
        else if (char === '\t') result += '\\t';
        else result += char;
      } else {
        result += char;
      }
    }
  }
  item.json.sanitized = result;
}
return $input.all();
